		}
	}
	return out
}

func lastJobs(t *testing.T, v *fakeView) jobs.ChangedMsg {
	t.Helper()
	seen := jobsSeen(v)
	if len(seen) == 0 {
		t.Fatal("the view was never handed a snapshot")
	}
	return seen[len(seen)-1]
