		},
		commandInput: newCommandInput(),
		suggester:    command.NewSuggester(),
		sugCursor:    -1,
		jobs:         jobs.New(),
		width:        width,
		height:       height,
	}
	// Lay it out once, as New() does, so the viewport height a test measures
	// against is the one the router actually computed.
	a.resize(width, height)
	return a
}

